std::vector<int> V1 = {1, 5, 8};
std::vector<int> V2 = {2, 4, 9, 10};
std::vector<int> Result; // Destination container

// Merges two sorted input ranges (V1, V2)
// into a single sorted output range (Result)
std::merge(V1.begin(), V1.end(),
           V2.begin(), V2.end(),
           std::back_inserter(Result));

// Time complexity: O(N + M)
// Result: {1, 2, 4, 5, 8, 9, 10}

